@startuml

enum PriorityScore {
  HIGH
  LOW
}

class HospitalHouseMD {
  + Name : string
}

class Patient {
  + Name : string
}

class Doctor {
  + Name : string
}

class Nurse {
  + Name : string
}

class Illness {
  + Name : string
  + PriorityScore : PriorityScore
}

class Treatment {
  + Stage : int
}

class Diagnosis {
  + Description : string
}

class ConsentForm {
  + Signed : boolean
}

HospitalHouseMD "1" -- "*" Patient
HospitalHouseMD "1" -- "*" Doctor
HospitalHouseMD "1" -- "*" Nurse
HospitalHouseMD "1" -- "*" Illness

Patient "1" -- "*" Diagnosis : receives
Doctor "1..*" -- "*" Diagnosis : makes
Diagnosis "1" -- "1" Illness : identifies
Diagnosis "1" -- "1" Doctor : approved by
Doctor "0..1" -- "1" Diagnosis : approves

Illness "1" -- "*" Treatment : has possible
Treatment "0..*" -- "1" Diagnosis : applied to
Treatment "0..*" -- "1" Patient : for

Patient "1" -- "0..1" ConsentForm : signs
Treatment "0..*" -- "0..1" ConsentForm : requires

Doctor "1" -- "*" Treatment : downgrades
Nurse "1..*" -- "*" Treatment : checks
Doctor "1..*" -- "*" Treatment : checks

@enduml

